  ProseChapter(
    'Cá bhfuil an t-ór: daingin, bainc agus saorstórais',
    [
      ProseSection(
        'Dúnta an óir: Fort Knox agus daingean an New York Fed',
        'Is é Fort Knox in Kentucky, stóras buillin na Stát Aontaithe, '
