  ProseChapter(
    'Platanam agus pallaidiam: uasal ach tionsclaíoch',
    [
      ProseSection(
        'Grúpa an phlatanaim: seisear gaolta neamhchoitianta',
        'Seachas ór agus airgead, aithníonn an t-áireamhán luacha dhá '
